using System;using System.IO;using System.Text;namespace AshkanSocial.Core.Services{public static class DiagnosticsService{public static string BuildReport(){var b=new StringBuilder();b.AppendLine("Ashkan Social Diagnostics");b.AppendLine("Generated: "+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));b.AppendLine("OS: "+Environment.OSVersion);b.AppendLine(".NET: "+Environment.Version);b.AppendLine("Machine: "+Environment.MachineName);b.AppendLine("64-bit process: "+Environment.Is64BitProcess);return b.ToString();}public static string SaveReport(string folder){Directory.CreateDirectory(folder);var path=Path.Combine(folder,"ashkan-social-diagnostics.txt");File.WriteAllText(path,BuildReport());return path;}}}